import { useState } from "react";
import SearchBar from "./SearchBar";

export default function Front() {
  const [searchBar, setSearchBar] = useState(false);

  return (
    <section className="z-10">
      <div className="sm:w-11/12 mx-auto">
        <div
          className={`relative w-full h-[620px] bg-homefrontbg bg-cover lg:bg-center bg-no-repeat bg-left sm:rounded-3xl overflow-hidden`}
        >
          {/* Dark gradient overlay for readability */}
          <div className="absolute inset-0 bg-gradient-to-b from-black/50 via-black/30 to-black/70"></div>

          {/* Content container */}
          <div className="relative z-10 flex flex-col justify-end h-full px-6 sm:px-12 pb-16">
            {/* Headline (Centered on mobile) */}
            <h1 className="text-white text-3xl sm:text-5xl font-bold sm:w-[70%] lg:w-[40%] leading-tight mb-8 sm:mb-12">
              Find the right funding, partners, and projects for climate change
            </h1>

            {/* Buttons + Search */}
            <div className="flex flex-wrap gap-4">
              {searchBar && (
                <form className="flex items-end gap-4 flex-wrap animate-fadeIn">
                  <SearchBar />
                  <button className="bg-white px-4 py-3 w-28 font-bold uppercase text-sm text-black rounded-md shadow-md hover:shadow-lg hover:scale-105 transition-all">
                    Find
                  </button>
                </form>
              )}

              {!searchBar && (
                <>
                  <button className="sm:text-lg bg-button-primary text-[#6C6252] hover:bg-button-primary-hover px-6 py-3 rounded-md capitalize font-bold shadow-md hover:shadow-lg hover:scale-105 transition-all">
                    Start Discovery
                  </button>

                  <button
                    onClick={() => setSearchBar(!searchBar)}
                    className="sm:text-lg text-white px-6 py-3 rounded-md border border-white font-bold shadow-md hover:shadow-lg hover:scale-105 transition-all"
                  >
                    Find Funding
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
